<template><section class="module-page operations-dashboard"><header class="module-heading action-heading"><div><h1>平台运维</h1><p>处理服务器、容器、镜像和平台基础服务运行态。</p></div><el-button icon="el-icon-refresh" :loading="loading" @click="load">刷新</el-button></header><section class="metric-strip"><div><small>处理服务器</small><strong>{{ agents.length }}</strong><span>{{ onlineAgents }} 在线 · {{ agents.length-onlineAgents }} 离线</span></div><div><small>容器模板</small><strong>{{ enabledTemplates }}</strong><span>可用固定版本</span></div><div><small>比赛环境</small><strong>{{ environments.length }}</strong><span>{{ readyEnvironments }} 个就绪</span></div><div><small>镜像任务</small><strong>{{ imageIssues.length }}</strong><span>待处理事项</span></div></section><section class="operations-layout"><div><header class="section-heading"><h2>需要处理</h2><span>{{ issues.length }} 项</span></header><div class="module-table-wrap"><el-table :data="issues" empty-text="当前没有待处理事项" size="small"><el-table-column label="类型" width="120"><template slot-scope="s"><el-tag size="mini" :type="s.row.level">{{ s.row.type }}</el-tag></template></el-table-column><el-table-column prop="name" label="对象" min-width="160" /><el-table-column prop="message" label="状态" min-width="220" /><el-table-column label="操作" width="110" align="right"><template slot-scope="s"><el-button type="text" @click="$router.push(s.row.route)">查看</el-button></template></el-table-column></el-table></div></div><aside><header class="section-heading"><h2>常用操作</h2></header><nav class="quick-actions"><router-link to="/operations/processing-agents"><i class="el-icon-cpu" /><span><strong>处理服务器</strong><small>注册、状态和命令</small></span></router-link><router-link to="/operations/container-templates"><i class="el-icon-box" /><span><strong>容器模板</strong><small>固定镜像和资源配置</small></span></router-link><router-link to="/operations/image-registry"><i class="el-icon-coin" /><span><strong>镜像仓库</strong><small>上传、审批、发布和推送</small></span></router-link><router-link to="/operations/competition-environments"><i class="el-icon-trophy" /><span><strong>比赛容器</strong><small>创建四槽位双容器</small></span></router-link></nav></aside></section></section></template>
<script>
import { listProcessingAgents } from '@/api/ProcessingAgents'
import { listContainerTemplates } from '@/api/ContainerTemplates'
import { listCompetitionEnvironments } from '@/api/CompetitionEnvironments'
import { listImageArtifacts, listImageDeployments } from '@/services/imageRegistry'
const value=r=>r&&r.data||[]
export default {name:'OperationsHome',data:()=>({loading:false,agents:[],templates:[],environments:[],artifacts:[],deployments:[]}),computed:{onlineAgents(){return this.agents.filter(x=>x.online).length},enabledTemplates(){return this.templates.filter(x=>x.enabled).length},readyEnvironments(){return this.environments.filter(x=>x.readiness==='READY').length},imageIssues(){return this.artifacts.filter(x=>x.reviewState==='PENDING_REVIEW'||x.importState==='FAILED').concat(this.deployments.filter(x=>x.state==='FAILED'))},issues(){const rows=[];this.agents.filter(x=>!x.online).forEach(x=>rows.push({type:'服务器离线',level:'danger',name:x.displayName||x.hostname||x.agentId,message:'Agent 心跳中断',route:'/operations/processing-agents'}));this.environments.filter(x=>['ERROR','DEGRADED'].includes(x.readiness)||x.actualState==='DEGRADED').forEach(x=>rows.push({type:'环境异常',level:'warning',name:`槽位 ${x.slotNumber}`,message:x.failureSummary||x.readinessCode||x.actualState,route:'/operations/competition-environments'}));this.imageIssues.forEach(x=>rows.push({type:'镜像任务',level:x.failureMessage?'danger':'warning',name:x.originalFilename||x.targetDigest||x.artifactId,message:x.failureMessage||x.failureCode||'等待审批',route:'/operations/image-registry'}));return rows}},created(){this.load()},methods:{async load(){this.loading=true;try{const [a,t,e,i,d]=await Promise.all([listProcessingAgents(),listContainerTemplates(),listCompetitionEnvironments(),listImageArtifacts({limit:200}),listImageDeployments({limit:200})]);this.agents=value(a);this.templates=value(t);this.environments=value(e);this.artifacts=value(i);this.deployments=value(d)}finally{this.loading=false}}}}
</script>
<style scoped>.action-heading,.section-heading{display:flex;align-items:center;justify-content:space-between}.operations-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:24px;margin-top:24px}.section-heading{min-height:48px;border-bottom:1px solid var(--ui-border)}.section-heading h2{margin:0;font-size:17px}.quick-actions{display:grid}.quick-actions a{display:grid;grid-template-columns:38px 1fr;align-items:center;gap:12px;min-height:72px;color:var(--ui-text);text-decoration:none;border-bottom:1px solid var(--ui-border)}.quick-actions i{display:grid;place-items:center;width:36px;height:36px;color:var(--ui-primary);background:#eef1ff;border-radius:6px}.quick-actions span{display:grid;gap:4px}.quick-actions small{color:var(--ui-muted)}@media(max-width:900px){.operations-layout{grid-template-columns:1fr}}</style>
